python -c "
import re
# Test different patterns with group extraction
patterns = {
    'lazy': r'([^ ]+?) *',
    'greedy': r'([^ ]+) *',
}

test_strings = [
    'hello       ',  # trailing spaces (padding)
    'hello',         # no padding  
    'hello world',   # space followed by more text
]

for name, pattern in patterns.items():
    print(f'Pattern: {pattern}')
    for s in test_strings:
        m = re.search(pattern, s)
        if m:
            print(f'  {repr(s):20} -> full={repr(m.group(0))}, group1={repr(m.group(1))}')
        else:
            print(f'  {repr(s):20} -> None')
    print()
"
